package com.rohit.inventory.entity;
import jakarta.persistence.*;
@Entity @Table(name="suppliers") public class Supplier extends BaseEntity { @Column(nullable=false,unique=true,length=40) private String code; @Column(nullable=false,length=180) private String name; @Column(name="contact_name") private String contactName; private String email; private String phone; @Column(name="address_line1") private String addressLine1; private String city; private String state; @Column(nullable=false) private String country="India"; @Enumerated(EnumType.STRING) @Column(nullable=false) private ProductStatus status=ProductStatus.ACTIVE; public String getCode(){return code;} public String getName(){return name;} public String getEmail(){return email;} public ProductStatus getStatus(){return status;} public void setCode(String v){code=v;} public void setName(String v){name=v;} public void setContactName(String v){contactName=v;} public void setEmail(String v){email=v;} public void setPhone(String v){phone=v;} public void setAddressLine1(String v){addressLine1=v;} public void setCity(String v){city=v;} public void setState(String v){state=v;} public void setCountry(String v){country=v;} public void setStatus(ProductStatus v){status=v;} }
